166:    const t0 = Date.now();
167:    let child;
168:    try {
169:      child = spawn(exe, [daemonJs, "--runtime", runtime, "--modules", modulesDir, "--db", db, "--out", out], {
170:        env: { ...process.env, ...env },
171:        detached: true,
172:        stdio: "ignore",
173:        windowsHide: true,
174:      });
175:      child.unref();
176:    } catch (e) {
177:      record(step, { ok: false, error: `spawn failed: ${String(e).slice(0, 200)}`, exe });
178:      return resolve();
179:    }
180:    const deadline = Date.now() + 30_000;
181:    const poll = setInterval(() => {
182:      if (fs.existsSync(out)) {
