30:function dirSizeMB(dir: string): number {
31:  let bytes = 0;
32:  const walk = (d: string) => {
33:    for (const n of readdirSync(d)) {
34:      const p = join(d, n);
35:      const st = statSync(p);
36:      if (st.isDirectory()) walk(p);
37:      else bytes += st.size;
38:    }
39:  };
40:  if (existsSync(dir)) walk(dir);
41:  return Math.round(bytes / 1024 / 1024);
42:}
