44:async function waitFor(pred: () => boolean, ms: number, label: string) {
45:  const deadline = Date.now() + ms;
46:  while (Date.now() < deadline) {
47:    if (pred()) return;
48:    await sleep(500);
49:  }
50:  throw new Error(`timeout ${ms}ms waiting for ${label}`);
51:}
